using System;using System.Drawing;using System.Drawing.Drawing2D;using System.IO;using System.Runtime.InteropServices;using Alfred;
class MakeIcon{[DllImport("user32.dll")]static extern bool DestroyIcon(IntPtr h);static void Main(){using(var orb=new OrbVisual())using(var b=new Bitmap(64,64))using(var g=Graphics.FromImage(b)){g.SmoothingMode=SmoothingMode.AntiAlias;g.ScaleTransform(2,2);orb.Draw(g,2.4,"recording",0.2f,false,false);IntPtr h=b.GetHicon();try{using(var i=Icon.FromHandle(h))using(var f=File.Create(@"F:\Alfred\installer\Alfred.ico"))i.Save(f);}finally{DestroyIcon(h);}}}}
